import sys, os
HERE=os.path.dirname(os.path.abspath(__file__)); OUT=os.path.join(HERE,'out'); os.makedirs(OUT,exist_ok=True)
from playwright.sync_api import sync_playwright
ROOT=os.path.abspath(os.path.join(HERE,'..','..'))+'/'; STUB=open(os.path.join(HERE,'stub.js')).read()
fails=[]
def ok(c,m):
    print(('PASS ' if c else 'FAIL ')+m)
    if not c: fails.append(m)
with sync_playwright() as p:
    b=p.chromium.launch()
    def page(init='',w=560,h=640):
        pg=b.new_page(viewport={'width':w,'height':h}); errs=[]
        pg.on('pageerror',lambda e:errs.append(str(e))); pg.on('console',lambda m: errs.append(m.text) if m.type=='error' else None)
        pg.add_init_script(STUB); pg.add_init_script(init); pg.goto('file://'+ROOT+'welcome.html'); pg.wait_for_timeout(400); pg.errs=errs; return pg
    calls=lambda pg,n: pg.evaluate("__S.calls.filter(c=>c[0]=='%s').map(c=>c[1])"%n)
    kbd=lambda pg: pg.eval_on_selector_all('#text kbd','e=>e.map(x=>x.textContent)')
    pg=page()
    ok(pg.inner_text('#title')=='Welcome to StickyPad','starts with a welcome')
    ok(kbd(pg)==['Ctrl + Alt + N'],'the new-note shortcut comes from the app (%s)'%kbd(pg))
    ok(not pg.is_visible('#back') and pg.is_visible('#skip'),'no Back on the first step, Skip is there')
    ok(pg.locator('#dots button').count()==6,'six steps')
    ok(pg.eval_on_selector_all('#scene .sc.on','e=>e.length')==1 and pg.eval_on_selector('#scene .sc.on','e=>e.dataset.s')=='0','one picture is shown, the first')
    ok(pg.eval_on_selector('.n','e=>getComputedStyle(e).animationName')=='drop','the notes are animated')
    # the optional name
    ok(pg.eval_on_selector('#nm','e=>document.activeElement===e'),'the name field has the keyboard')
    pg.fill('#nm','Alex'); ok(pg.inner_text('#title')=='Welcome, Alex!','the title follows what is typed')
    pg.wait_for_timeout(600); ok(calls(pg,'prefs')[-1]=={'name':'Alex'},'the name is saved (%s)'%calls(pg,'prefs'))
    pg.fill('#nm','  '+'x'*50); pg.wait_for_timeout(600); ok(0 < len(calls(pg,'prefs')[-1]['name']) <= 30,'at most 30 letters')
    pg.fill('#nm','<img src=x onerror=alert(1)>'); ok(pg.eval_on_selector('#title','e=>e.querySelector("img")')==None,'a name is text, never HTML')
    pg.fill('#nm',''); pg.wait_for_timeout(500); ok(pg.inner_text('#title')=='Welcome to StickyPad' and calls(pg,'prefs')[-1]=={'name':''},'empty goes back to the plain welcome')
    pg.fill('#nm','Al'); pg.keyboard.press('ArrowLeft'); ok(pg.inner_text('#title')=='Welcome, Al!','arrow keys move the cursor in the field, not the steps')
    pg.keyboard.press('Enter'); pg.wait_for_timeout(600); ok(pg.inner_text('#title')=='Pick your look','Enter in the field goes on')
    # the look
    ok(pg.locator('.th').count()==8 and not pg.is_visible('#scene'),'eight looks, no picture on this step')
    ok(pg.eval_on_selector('#card','e=>e.classList.contains("wide")'),'the card is wider here')
    pg.wait_for_timeout(800); pg.screenshot(path=os.path.join(OUT,'welcome_look.png'))
    pg.click('.th[data-id=forest]'); pg.wait_for_timeout(100)
    ok(calls(pg,'themeApplyAll')==['forest'] and not calls(pg,'themeSet'),'on a first run the look is applied to the first note too')
    ok(pg.eval_on_selector('.th[data-id=forest]','e=>e.getAttribute("aria-pressed")')=='true','the chosen look is marked')
    pg.click('.seg [data-m=dark]'); pg.wait_for_timeout(100); ok(calls(pg,'settingsSet')[-1]=={'mode':'dark'},'dark mode is sent')
    pg.click('.seg [data-m=system]'); pg.wait_for_timeout(100); ok(calls(pg,'settingsSet')[-1]=={'mode':'system'},'and "Match Windows"')
    # comfort options
    pg.click('#next'); pg.wait_for_timeout(600); ok(pg.inner_text('#title')=='Make it comfortable' and not pg.is_visible('#scene'),'the comfort step comes after the look')
    ok(pg.locator('.seg button').count()==4 and pg.locator('.opt input').count()==3,'four sizes, three switches')
    pg.click('.seg [data-size="130"]'); pg.wait_for_timeout(100); ok(calls(pg,'accessSet')[-1]=={'size':130},'a size is applied straight away')
    pg.check('.opt input[data-k=contrast]'); pg.wait_for_timeout(100); ok(calls(pg,'accessSet')[-1]=={'contrast':True},'high contrast is applied straight away')
    pg.check('.opt input[data-k=motion]'); pg.wait_for_timeout(100); ok(calls(pg,'accessSet')[-1]=={'motion':True},'so is reduce motion')
    ok(pg.eval_on_selector('.seg [data-size="130"]','e=>e.getAttribute("aria-pressed")')=='true','the chosen size is marked')
    pg.screenshot(path=os.path.join(OUT,'welcome_comfort.png'))
    pg.click('#next'); pg.wait_for_timeout(600); ok('Find anything'==pg.inner_text('#title'),'Next goes on'); ok(pg.eval_on_selector('#scene .sc.on','e=>e.dataset.s')=='1' and pg.is_visible('#scene'),'the picture comes back')
    ok(kbd(pg)==['Ctrl + Alt + Q','Ctrl + Alt + F'],'search and Home shortcuts shown')
    pg.keyboard.press('ArrowRight'); pg.wait_for_timeout(600); ok('AI helper' in pg.inner_text('#title'),'arrow keys work too')
    pg.keyboard.press('ArrowLeft'); ok(pg.inner_text('#title')=='Find anything','and back')
    pg.click('#dots button:nth-child(5)'); pg.wait_for_timeout(600); ok('AI helper' in pg.inner_text('#title'),'a dot jumps to a step')
    pg.click('#extra .btn'); pg.wait_for_timeout(100)
    ok(calls(pg,'welcomeClose')==[{'go':'settings','section':'ai'}],'the AI step opens the AI settings (%s)'%calls(pg,'welcomeClose'))
    pg.click('#dots button:nth-child(6)'); pg.wait_for_timeout(2600); pg.screenshot(path=os.path.join(OUT,'welcome5.png'))
    ok('safe' in pg.inner_text('#title') and pg.inner_text('#next')=='Start with a note' and not pg.is_visible('#skip'),'last step: Start with a note, no Skip')
    pg.click('#next'); pg.wait_for_timeout(100); ok(calls(pg,'welcomeClose')[-1]=={'go':'note'},'the last button starts with a note')
    # opened again later (not a first run): never recolours notes
    pg7=page("window.__FRESH=false;"); pg7.click('#next'); pg7.wait_for_timeout(600); pg7.click('.th[data-id=ocean]'); pg7.wait_for_timeout(100)
    ok(calls(pg7,'themeSet')==['ocean'] and not calls(pg7,'themeApplyAll'),'opened again later: only the app look changes, your notes keep their colours')
    pr=b.new_page(viewport={'width':560,'height':640},reduced_motion='reduce'); pr.add_init_script(STUB); pr.goto('file://'+ROOT+'welcome.html'); pr.wait_for_timeout(300)
    ok(pr.eval_on_selector('.n','e=>getComputedStyle(e).animationName')=='none','with "reduce motion" nothing moves')
    pg2=page(); pg2.click('#skip'); pg2.wait_for_timeout(100); ok(calls(pg2,'welcomeClose')==[{}],'Skip closes without doing anything')
    pg2b=page(); pg2b.fill('#nm','Zoe'); pg2b.click('#skip'); pg2b.wait_for_timeout(100); ok(calls(pg2b,'prefs')[-1]=={'name':'Zoe'},'a name typed just before closing is not lost')
    pg3=page(); pg3.keyboard.press('Escape'); pg3.wait_for_timeout(100); ok(calls(pg3,'welcomeClose')==[{}],'Esc closes')
    pg4=page("window.__NAME='Alex';"); ok(pg4.inner_text('#title')=='Welcome, Alex!' and pg4.input_value('#nm')=='Alex','a known name is shown and kept')
    pg6=page(w=420,h=480); ok(pg6.eval_on_selector('main','e=>e.scrollWidth<=e.clientWidth+1') and pg6.is_visible('#next'),'fits the smallest window')
    pg6.click('#next'); pg6.wait_for_timeout(600); ok(pg6.eval_on_selector('main','e=>e.scrollWidth<=e.clientWidth+1') and pg6.is_visible('#next') and pg6.locator('.th').count()==8,'the look step fits too')
    for q in (pg,pg2,pg2b,pg3,pg4,pg6,pg7): ok(not q.errs,'no page errors (%s)'%q.errs)
    b.close()
print('FAILED: %s'%fails if fails else 'ALL PASS'); sys.exit(1 if fails else 0)
